import sys,subprocess,os,json,hashlib,datetime,time,pathlib
root=pathlib.Path.cwd(); evidence=root/'docs/plans/2026-09-25-mimo-session-resilience_evidence/2026-10-27-hook-correction'; scratch=root/'_scratch/hook-correction'
label=sys.argv[1]; command=sys.argv[2:]; env=os.environ.copy(); env['PATH']='/Users/suas/.nvm/versions/node/v24.22.1/bin:'+env['PATH']; env['AIO_TEST_SUMMARY']='0';env['AIO_TEST_NO_CACHE']='1';env['AIO_TEST_OUT_SUFFIX']='hook-correction-'+label
if label == 'build-main':
 while not (evidence/'source-hook-receipt.json').exists():
  time.sleep(5)
log=scratch/(label+'.log');start=datetime.datetime.now(datetime.timezone.utc).isoformat();print('START '+label,flush=True)
with log.open('w') as f: r=subprocess.run(command,env=env,stdout=f,stderr=subprocess.STDOUT)
raw=log.read_bytes(); text=raw.decode(errors='replace'); lines=text.splitlines(); out={'at':start,'finished':datetime.datetime.now(datetime.timezone.utc).isoformat(),'command':command,'exit':r.returncode,'fullOutput':str(log.relative_to(root)),'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'output':text if len(raw)<18000 else '\n'.join(lines[-90:]),'outputComplete':len(raw)<18000}
report=root/'_scratch'/('test-results.hook-correction-'+label+'.json')
if report.exists():
 data=json.loads(report.read_text());out['testSummary']={k:data.get(k) for k in ['success','numTotalTestSuites','numPassedTestSuites','numFailedTestSuites','numTotalTests','numPassedTests','numFailedTests','numPendingTests','numRuntimeErrorTestSuites']};out['failedTests']=[{'file':x.get('name'),'name':a.get('fullName'),'failureMessages':a.get('failureMessages')} for x in data.get('testResults',[]) for a in x.get('assertionResults',[]) if a.get('status')=='failed']
(evidence/(label+'-receipt.json')).write_text(json.dumps(out,indent=2)+'\n');print('EXIT '+label+' '+str(r.returncode),flush=True);print(text[-7000:] if r.returncode else '\n'.join(lines[-4:]),flush=True);sys.exit(r.returncode)

